/* @socom-skeleton body FilterMissionFolder__FPCcPCcPCcPc */
s32 FilterMissionFolder(const char* prefix, const char* infix, const char* postfix, char* output)
{
	s32 result = 0;

	if (!infix)
	{
		infix = "/";
	}

	// Multiplayer map?
	if (strncmp(prefix, "mp", 2) == 0)
	{
		result = snprintf(output, 128, "%s/mp/%s", infix, postfix);
	}
	else
	{
		// Singleplayer map?
		if (strncmp(prefix, "m", 1) == 0)
		{
			result = snprintf(output, 128, "%s/sp/%s", infix, postfix);
		}
		else
		{
			result = snprintf(output, 128, "%s/%s", infix, postfix);
		}
	}

	return result;
}

